def _resolve_size(self, size: int | None) -> int:
    if size is None:
        return len(self)
    if not isinstance(size, int):
        raise TypeError("size must be an integer")
    if not 0 <= size <= len(self):
        raise ValueError(f"size must be within 0..{len(self)}")
